 rel=str(f.relative_to(p))
 if re.search('crown|tournament|bunkbed|hat-bipartite-cycle-formal-pi-r2|polynexus-rook-formal-pi-r1',rel,re.I):raise RuntimeError('Unexpected protected name inside own lane; not opened')
