for rel,e in v['files'].items():
 b=(p/rel).read_bytes();assert len(b)==e['bytes'] and hashlib.sha256(b).hexdigest()==e['sha256'],rel
expected='755f13daeedabfd4cb1e66d6b85956013e6727e2de8adfe7de351fdf73c3dfad';assert hashlib.sha256((p/'reservation.json').read_bytes()).hexdigest()==expected;assert (p/'reservation.sha256').read_text().strip()==expected
