for k,x in raw.items():
 b=(p/'raw'/f'{k}.jsonl').read_bytes();assert b==base64.b64decode(x['raw_base64']) and hashlib.sha256(b).hexdigest()==x['raw_sha256'];assert json.loads(b)==x['object'];assert hashlib.sha256(x['object']['statement'].encode()).hexdigest()==x['statement_sha256']
